def solve(g):
    R,C=len(g),len(g[0])
    o=[row[:] for row in g]
    for r in range(R):
        for c in range(C):
            if g[r][c]!=1: continue
            rowl=any(g[r][k]==9 for k in range(c)); rowr=any(g[r][k]==9 for k in range(c+1,C))
            colu=any(g[k][c]==9 for k in range(r)); cold=any(g[k][c]==9 for k in range(r+1,R))
            if (rowl and rowr) or (colu and cold): o[r][c]=3
    return o
